13 | 	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
14 | 	let output = "";
15 | 	for (let index = 0; index < bytes.length; index += 3) {
16 | 		const first = bytes[index] ?? 0;
17 | 		const second = bytes[index + 1];
18 | 		const third = bytes[index + 2];
